import 'dart:async';

import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';

/// Sound effects + music. Files live in assets/audio (generated by
/// tool/gen_audio.py). Tests and headless runs use [SilentAudioService].
abstract class AudioService {
  Future<void> init();

  void setVolumes({double? sfx, double? music});

  /// Plays a one-shot effect, e.g. `sfx('splash', volume: 0.5)`.
  void sfx(String name, {double volume = 1});

  /// Switches the looping music track; null stops music. Repeating the
  /// current track is a no-op.
  void music(String? track);

  /// Call on any user gesture. Browsers block audio until the first tap,
  /// so music requested before that starts here.
  void unlock();
}

class SilentAudioService implements AudioService {
  @override
  Future<void> init() async {}
  @override
  void setVolumes({double? sfx, double? music}) {}
  @override
  void sfx(String name, {double volume = 1}) {}
  @override
  void music(String? track) {}
  @override
  void unlock() {}
}

class FlameAudioService implements AudioService {
  FlameAudioService({this.sfxVolume = 0.8, this.musicVolume = 0.5});

  /// Effects that fire often get a pool of players for low latency and overlap.
  static const _pooled = {'shot_pistol': 5, 'shot_rifle': 5, 'shot_launcher': 3, 'hit': 4, 'splash': 3, 'ui_click': 2};
  static const _oneShots = ['hurt', 'tag_out', 'pickup', 'reload', 'plant', 'haze_warning', 'win', 'lose'];

  double sfxVolume, musicVolume;
  final Map<String, AudioPool> _pools = {};
  final Map<String, double> _lastPlayed = {};
  final Stopwatch _clock = Stopwatch()..start();
  bool _ready = false;
  bool _unlocked = !kIsWeb;
  String? _wantTrack;
  String? _playingTrack;

  @override
  Future<void> init() async {
    try {
      await FlameAudio.bgm.initialize();
      await FlameAudio.audioCache.loadAll([
        for (final n in [..._pooled.keys, ..._oneShots]) '$n.wav',
      ]);
      for (final e in _pooled.entries) {
        _pools[e.key] = await FlameAudio.createPool('${e.key}.wav', maxPlayers: e.value);
      }
      _ready = true;
      _applyMusic();
    } catch (e) {
      debugPrint('Audio disabled: $e');
    }
  }

  @override
  void setVolumes({double? sfx, double? music}) {
    if (sfx != null) sfxVolume = sfx;
    if (music != null) {
      musicVolume = music;
      if (_playingTrack != null) {
        _quiet(FlameAudio.bgm.audioPlayer.setVolume(musicVolume));
      }
      if (musicVolume <= 0.001) {
        _stopMusic();
      } else {
        _applyMusic();
      }
    }
  }

  @override
  void sfx(String name, {double volume = 1}) {
    if (!_ready || !_unlocked) return;
    final v = (volume * sfxVolume).clamp(0.0, 1.0);
    if (v < 0.02) return;
    // Don't stack the same sound within 35 ms (25 bots can fire at once).
    final now = _clock.elapsedMilliseconds / 1000;
    if (now - (_lastPlayed[name] ?? -1) < 0.035) return;
    _lastPlayed[name] = now;
    try {
      final pool = _pools[name];
      _quiet(pool != null ? pool.start(volume: v) : FlameAudio.play('$name.wav', volume: v));
    } catch (_) {
      // Never let a sound break the game.
    }
  }

  @override
  void music(String? track) {
    _wantTrack = track;
    if (track == null) {
      _stopMusic();
    } else {
      _applyMusic();
    }
  }

  @override
  void unlock() {
    if (_unlocked) return;
    _unlocked = true;
    _applyMusic();
  }

  void _applyMusic() {
    final track = _wantTrack;
    if (!_ready || !_unlocked || track == null || musicVolume <= 0.001) return;
    if (_playingTrack == track) return;
    _playingTrack = track;
    unawaited(
      FlameAudio.bgm
          .play('$track.wav', volume: musicVolume)
          .then<void>(
            (_) {},
            onError: (Object e) {
              // Autoplay blocked or similar: try again on the next tap.
              _playingTrack = null;
              if (kIsWeb) _unlocked = false;
            },
          ),
    );
  }

  void _stopMusic() {
    if (_playingTrack == null) return;
    _playingTrack = null;
    _quiet(FlameAudio.bgm.stop());
  }

  /// Fire-and-forget: audio failures are logged in debug and otherwise ignored.
  static void _quiet(Future<Object?> f) =>
      unawaited(f.then<void>((_) {}, onError: (Object e) => debugPrint('audio: $e')));
}
